import { sprite, type Sprite } from '../../canvas'

/*
 * A `sprite()` grid kept at the full 24x24 part canvas. `sprite()` drops blank rows under the drawing and
 * blank columns right of it (its width is the longest row), so a hair part drawn in rows 3-7 would come back
 * five rows tall and its origin would no longer point at the same pixel. The generated parts use this instead.
 * Hand-written helper; the files beside it are generated by tools/art/aseprite-import.ts.
 */
export const PART_SIZE = 24

export function grid24(text: string): Sprite {
  const s = sprite(text)
  const rows = s.rows.slice(0, PART_SIZE).map((row) => row.slice(0, PART_SIZE).padEnd(PART_SIZE, ' '))
  while (rows.length < PART_SIZE) rows.push(' '.repeat(PART_SIZE))
  return { width: PART_SIZE, height: PART_SIZE, rows }
}
